    const m = r.i(-2, 4), d = r.i(1, 4), X = [m - d, m, m + d], ps = [r.i(1, 4)]; ps.push(r.i(1, 9 - 2 * ps[0])); ps.push(ps[0]); if(ps[0] * 2 + ps[1] !== 10) ps[1] = 10 - 2 * ps[0]; if(ps[1] < 1) return null;
    const tbl = X.map((x, i) => `${fmt(x)}: ${fmt(ps[i] / 10)}`).join(', '), E = m, D = d * d * (2 * ps[0]) / 10;
